(async()=>{const bs=T.BattleScene;const out={};const fails=[];const CHK=(k,v)=>{out[k]=v;if(v!==true)fails.push(k+':'+JSON.stringify(v));};
if(!bs)return JSON.stringify({noBattle:true,allOk:false,fails:['no-battle']});
const atk=bs.partyMembers[0];const es=bs.troop.aliveMembers();
// 1) 防御减伤: 守卫目标受击 ≈ floor(裸伤/2)(裸伤=公式+方差) 
let guardOk=false;for(let tryIdx=0;tryIdx<5&&!guardOk;tryIdx++){const e0=es[tryIdx%es.length],e1=es[(tryIdx+1)%es.length];const h0=e0.hp;bs.applyToBattler(atk,T.$dataSkills[1],e0);const rawDmg=h0-e0.hp;e1._guarding=true;const h1=e1.hp;bs.applyToBattler(atk,T.$dataSkills[1],e1);const guardDmg=h1-e1.hp;e1._guarding=false;const expectFloor=Math.floor(rawDmg/2);out.guard={raw:rawDmg,guarded:guardDmg,floorHalf:expectFloor};guardOk=Math.abs(guardDmg-expectFloor)<=Math.max(2,Math.ceil(rawDmg*0.15)+1)&&guardDmg<=rawDmg;if(guardOk)break;}
CHK('guardHalf',guardOk);
// 2) 逃跑成功: 全队速度大幅提高 → chance=1
for(const a of bs.partyMembers){a._paramBonus=a._paramBonus||{};a._paramBonus[6]=5000;}
bs.tryEscape();out.esc=bs.phase;CHK('escapeWin',bs.phase==='escaped'&&bs.logLines.some(l=>l.includes('成功逃跑了')));
// 3) 逃跑失败路径: 速度压到 0 → chance=0.05, 数次内必见一次失败回 resolve
let sawFail=false;
for(const a of bs.partyMembers){a._paramBonus=a._paramBonus||{};a._paramBonus[6]=-99999;}
for(let i=0;i<12;i++){bs.phase='actor-cmd';const ln=bs.logLines.length;bs.tryEscape();if(bs.phase==='resolve'&&bs.logLines.slice(ln).some(l=>l.includes('逃跑失败了'))){sawFail=true;break;}}
out.failPath=sawFail?'resolve-ok':'never-failed';CHK('escapeFailPath',sawFail);
// 4) 逃跑结束战场解绑
bs.phase='escaped';bs.phaseTimer=5;await new Promise(r=>setTimeout(r,700));out.troopFreed=T.$gameTroop===null;CHK('troopFreed',T.$gameTroop===null);
out.allOk=fails.length===0;out.fails=fails;
return JSON.stringify(out);})()
